<?php
require_once __DIR__."/../config/app.php"; require_login(); $u=current_user(); $q=trim((string)($_GET["q"]??"")); $status=trim((string)($_GET["status"]??""));
$sql="SELECT p.*,u.name user_name,s.name scheme_name,pe.year,pe.wave FROM proposals p JOIN users u ON u.id=p.user_id JOIN schemes s ON s.id=p.scheme_id JOIN periods pe ON pe.id=p.period_id WHERE 1=1";$params=[];
if(has_role("Dosen")){$sql.=" AND p.user_id=?";$params[]=$u["id"];} if($status!==""){$sql.=" AND p.status=?";$params[]=$status;} if($q!==""){$sql.=" AND (p.title LIKE ? OR u.name LIKE ?)";$params[]="%$q%";$params[]="%$q%";}$sql.=" ORDER BY p.id DESC";$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$pageTitle="Proposal";require __DIR__."/../partials/header.php";?>
<div class="d-flex justify-content-between mb-4"><div><h3 class="fw-bold">Data Proposal</h3><p class="text-muted">Create, Read, Update, Delete proposal.</p></div><?php if(has_role("Dosen","Admin LP2M")):?><a class="btn btn-primary" href="create.php">+ Tambah Proposal</a><?php endif;?></div>
<form class="card p-3 mb-3"><div class="row g-2"><div class="col-md-5"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Cari judul/dosen"></div><div class="col-md-4"><select class="form-select" name="status"><option value="">Semua Status</option><?php foreach(["Draft","Menunggu Verifikasi","Menunggu Penilaian","Dinilai Reviewer","Diterima","Ditolak"] as $s):?><option <?= $status===$s?"selected":""?>><?=e($s)?></option><?php endforeach;?></select></div><div class="col-md-3"><button class="btn btn-outline-primary w-100">Filter</button></div></div></form>
<div class="card p-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>No</th><th>Judul</th><th>Dosen</th><th>Skema</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
<?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><strong><?=e($r["title"])?></strong></td><td><?=e($r["user_name"])?></td><td><?=e($r["scheme_name"])?></td><td><span class="badge bg-secondary"><?=e($r["status"])?></span></td><td><a class="btn btn-sm btn-outline-primary" href="view.php?id=<?=$r["id"]?>">Lihat</a> <?php if(can_edit_proposal($r)):?><a class="btn btn-sm btn-outline-warning" href="edit.php?id=<?=$r["id"]?>">Edit</a><?php endif;?> <?php if(can_delete_proposal($r)):?><form class="d-inline" method="post" action="delete.php" onsubmit="return confirm('Hapus proposal?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r["id"]?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?>
<?php if(!$rows):?><tr><td colspan="6" class="text-center text-muted">Belum ada proposal.</td></tr><?php endif;?></tbody></table></div></div>
<?php require __DIR__."/../partials/footer.php";?>